55	const PROCESSING_FEE = 5;
56	
57	const BASE_PREMIUMS = {
58	  sword: 100,
59	  amulet: 60,
60	  staff: 80,
61	  potion: 40,
62	  rune: 25,
63	  moonstone: 25,
64	} as const satisfies Record<string, number>;
65	
66	type PricedItemType = keyof typeof BASE_PREMIUMS;
67	
68	const hasBasePremium = (type: string): type is PricedItemType =>
69	  type in BASE_PREMIUMS;
70	
71	// Unknown item types are not yet rejected — the spec requires an error, but no
72	// test drives that behaviour yet, so they are priced at 0 for the moment.
73	const UNPRICED_UNKNOWN_TYPE = 0;
74	
75	const basePremiumForItem = (item: Item): number =>
76	  hasBasePremium(item.type)
77	    ? BASE_PREMIUMS[item.type]
78	    : UNPRICED_UNKNOWN_TYPE;
79	
80	const BLOCK_SIZE = 3;
81	
82	const BLOCK_BASE_PREMIUM = 60;
83	
84	const sum = (amounts: number[]): number =>
85	  amounts.reduce((total, amount) => total + amount, 0);
86	
87	// "Alike" means the same exact type, not merely the same family: two runes and
88	// a moonstone are three components but not three alike ones, so grouping them
89	// by type keeps them apart and denies them the block price.
90	const groupByType = (items: Item[]): Item[][] => {
91	  const groups = new Map<string, Item[]>();
92	  for (const item of items) {
93	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
94	  }
95	  return [...groups.values()];
96	};
97	
98	// A block is not carved out of a larger group: the block price applies only
99	// when the group consists of exactly three alike components (7 runes cost
100	// 7 × 25, not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only
101	// ever passes a single group from groupByType.
102	const basePremiumForGroup = (group: Item[]): number =>
103	  group.length === BLOCK_SIZE
104	    ? BLOCK_BASE_PREMIUM
105	    : sum(group.map(basePremiumForItem));
106	
107	const basePremiumForItems = (items: Item[]): number =>
108	  sum(groupByType(items).map(basePremiumForGroup));
109	
110	const CURSE_SURCHARGE = 0.5;
111	
112	// Every modifier is an additive percentage of its OWN base — modifiers never
113	// compound with each other. Item-scoped modifiers take the affected item's base
114	// premium as their base; policy-scoped modifiers take the policy base premium
115	// (the sum of all item base premiums). So the total is always
116	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
117	const modifierAmount = (rate: number, base: number): number => rate * base;
118	
119	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
120	
121	const HIGH_ENCHANTMENT_THRESHOLD = 5;
122	
123	const isCursed = (item: Item): boolean => item.cursed === true;
124	
125	const isHighlyEnchanted = (item: Item): boolean =>
126	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
127	
128	interface ItemModifier {
129	  rate: number;
130	  appliesTo: (item: Item) => boolean;
131	}
132	
133	// Each item-scoped modifier is a row: a rate and the condition under which it
134	// applies. The predicate names the modifier, so a row needs no separate label.
135	// Adding a modifier means adding a row, not a new branch.
136	const ITEM_MODIFIERS: ItemModifier[] = [
137	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
138	  { rate: HIGH_ENCHANTMENT_SURCHARGE, appliesTo: isHighlyEnchanted },
139	];
140	
141	const itemModifierRates = (item: Item): number[] =>
142	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
143	    (modifier) => modifier.rate,
144	  );
145	
146	const LOYALTY_DISCOUNT = 0.2;
147	
148	const LOYALTY_THRESHOLD_YEARS = 2;
149	
150	const isLongStanding = (customer: Customer): boolean =>
151	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
152	
153	// Discounts are surcharges with the sign flipped: expressing one as a negative
154	// rate lets it flow through the same additive sum as every surcharge, with no
155	// separate subtraction step. Discount constants stay positive magnitudes and
156	// are negated here, at the point of use, so the direction is visible in the
157	// rate list rather than buried in a constant's sign.
158	const asDiscount = (rate: number): number => -rate;
159	
160	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
161	
162	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
163	
164	// Policy-scoped modifiers apply to the policy base premium. Unlike item
165	// modifiers they select on the customer and on the quote's position in the
166	// scenario rather than on an item.
167	//
168	// The initial-assessment surcharge applies to every quote: each item is treated
169	// as a first insurance regardless of customer history. The follow-up discount
170	// is what distinguishes a customer's later contracts.
171	const policyModifierRates = (
172	  customer: Customer,
173	  isFollowUpContract: boolean,
174	): number[] => [
175	  INITIAL_ASSESSMENT_SURCHARGE,
176	  ...(isLongStanding(customer) ? [asDiscount(LOYALTY_DISCOUNT)] : []),
177	  ...(isFollowUpContract ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT)] : []),
178	];
179	
180	const itemModifiersTotal = (items: Item[]): number =>
181	  sum(
182	    items.flatMap((item) =>
183	      itemModifierRates(item).map((rate) =>
184	        modifierAmount(rate, basePremiumForItem(item)),
185	      ),
186	    ),
187	  );
188	
189	const policyModifiersTotal = (
190	  policyBasePremium: number,
191	  customer: Customer,
192	  isFollowUpContract: boolean,
193	): number =>
194	  sum(
195	    policyModifierRates(customer, isFollowUpContract).map((rate) =>
196	      modifierAmount(rate, policyBasePremium),
197	    ),
198	  );
199	
200	// All amounts are rounded to whole G in the MHPCO's favour. For a premium —
201	// money flowing to the MHPCO — its favour is upwards. The payout half of this
202	// rule rounds the other way, but no test drives payouts yet, so only the
203	// premium direction is named here.
204	const roundPremiumInMHPCOsFavour = (amount: number): number =>
205	  Math.ceil(amount);
206	
207	const quotePremium = (
208	  items: Item[],
209	  customer: Customer,
210	  isFollowUpContract: boolean,
211	): number => {
212	  const policyBasePremium = basePremiumForItems(items);
213	  return roundPremiumInMHPCOsFavour(
214	    policyBasePremium +
215	      itemModifiersTotal(items) +
216	      policyModifiersTotal(policyBasePremium, customer, isFollowUpContract) +
217	      PROCESSING_FEE,
218	  );
219	};
220	
221	// Steps are not independent: a quote's premium depends on how many quotes came
222	// before it, and the pending claim operation will depend on the policies those
223	// quotes created. So a step is a function from state to (result, next state),
224	// and the scenario is a fold over that — not a map, which would promise an
225	// independence the steps do not have.
226	// An item's insurance value is what it is insured FOR, independent of what it
227	// costs to insure — so it is a separate table from BASE_PREMIUMS.
228	const INSURANCE_VALUES = {
229	  sword: 1000,
230	  amulet: 600,
231	  staff: 800,
232	  potion: 400,
233	  rune: 250,
234	  moonstone: 250,
235	} as const satisfies Record<string, number>;
236	
237	const insuranceValueForItem = (item: Item): number =>
238	  hasBasePremium(item.type) ? INSURANCE_VALUES[item.type] : 0;
239	
240	const insuranceSum = (items: Item[]): number =>
241	  sum(items.map(insuranceValueForItem));
242	
243	const CAP_MULTIPLE = 2;
244	
245	const DEDUCTIBLE = 100;
246	
247	interface Policy {
248	  items: Item[];
249	  remainingCap: number;
250	}
251	
252	// Policies are keyed by the index of the quote step that created them: a claim
253	// step names its policy by that zero-based index.
254	interface ScenarioState {
255	  quotesSoFar: number;
256	  policies: Map<number, Policy>;
257	}
258	
259	const INITIAL_STATE: ScenarioState = {
260	  quotesSoFar: 0,
261	  policies: new Map(),
262	};
263	
264	interface StepOutcome {
265	  result: StepResult;
266	  state: ScenarioState;
267	}
268	
269	const runQuote = (
270	  step: QuoteStep,
271	  customer: Customer,
272	  state: ScenarioState,
273	  stepIndex: number,
274	): StepOutcome => ({
275	  result: {
276	    premium: quotePremium(step.items, customer, state.quotesSoFar > 0),
277	  },
278	  state: {
279	    quotesSoFar: state.quotesSoFar + 1,
280	    policies: new Map(state.policies).set(stepIndex, {
281	      items: step.items,
282	      remainingCap: CAP_MULTIPLE * insuranceSum(step.items),
283	    }),
284	  },
285	});
286	
287	const payoutForDamage = (damage: Damage): number =>
288	  damage.amount - DEDUCTIBLE;
289	
290	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
291	  const policy = state.policies.get(step.policy)!;
292	  const payout = sum(step.incident.damages.map(payoutForDamage));
293	  const remainingCap = policy.remainingCap - payout;
294	  return {
295	    result: { payout, remainingCap },
296	    state: {
297	      ...state,
298	      policies: new Map(state.policies).set(step.policy, {
299	        ...policy,
300	        remainingCap,
301	      }),
302	    },
303	  };
304	};
305	
306	// Dispatch decides once what a step is; each operation then owns both its
307	// result and how it advances the state, so no caller has to re-test step.op to
308	// know what the step did.
309	const runStep = (
310	  step: Step,
311	  customer: Customer,
312	  state: ScenarioState,
313	  stepIndex: number,
314	): StepOutcome =>
315	  step.op === "quote"
316	    ? runQuote(step, customer, state, stepIndex)
317	    : runClaim(step, state);
318	
319	// The fold carries both halves of the outcome: the results accumulated so far
320	// and the state the next step will see. Threading the state explicitly (rather
321	// than recovering it from the last result) keeps the dependency between steps
322	// visible in the type.
323	interface ScenarioRun {
324	  results: StepResult[];
325	  state: ScenarioState;
326	}
327	
328	const INITIAL_RUN: ScenarioRun = { results: [], state: INITIAL_STATE };
329	
330	const appendStep =
331	  (customer: Customer) =>
332	  (run: ScenarioRun, step: Step, stepIndex: number): ScenarioRun => {
333	    const outcome = runStep(step, customer, run.state, stepIndex);
334	    return {
335	      results: [...run.results, outcome.result],
336	      state: outcome.state,
337	    };
338	  };
339	
340	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
341	  results: steps.reduce(appendStep(customer), INITIAL_RUN).results,
342	});
