// insure) and insurance value (what it is insured FOR) are independent numbers,
// but they are known for exactly the same set of types — so they belong in one
// table. Keeping them apart would leave two key sets that must agree with
// nothing enforcing it.
interface ItemSpec {
  basePremium: number;
  insuranceValue: number;
}

const ITEM_SPECS = {
  sword: { basePremium: 100, insuranceValue: 1000 },
  amulet: { basePremium: 60, insuranceValue: 600 },
  staff: { basePremium: 80, insuranceValue: 800 },
  potion: { basePremium: 40, insuranceValue: 400 },
  rune: { basePremium: 25, insuranceValue: 250 },
  moonstone: { basePremium: 25, insuranceValue: 250 },
} as const satisfies Record<string, ItemSpec>;

type KnownItemType = keyof typeof ITEM_SPECS;

const isKnownItemType = (type: string): type is KnownItemType =>
  type in ITEM_SPECS;

// Unknown item types are not yet rejected — the spec requires an error, but no
// test drives that behaviour yet, so they carry zeroes for the moment.
const UNKNOWN_TYPE_SPEC: ItemSpec = { basePremium: 0, insuranceValue: 0 };

const specForItem = (item: Item): ItemSpec =>
  isKnownItemType(item.type) ? ITEM_SPECS[item.type] : UNKNOWN_TYPE_SPEC;

const basePremiumForItem = (item: Item): number => specForItem(item).basePremium;

